const crypto = require('crypto');
const secret = $env.WEBHOOK_HMAC_SECRET || 'lp_dev_hmac_secret_change_in_prod_9f8e7d6c';
const slackPayload = typeof $json.body.payload === 'string' ? JSON.parse($json.body.payload) : $json.body;
const actionVal = JSON.parse(slackPayload.actions[0].value);
const callbackBody = {
  approval_id: actionVal.approval_id,
  decision: actionVal.decision,
  approver_email: slackPayload.user?.email || 'manager@ledgerpilot.io',
  reason: `Slack Block Kit ${actionVal.decision} by ${slackPayload.user?.username || 'approver'}`,
  slack_message_ts: slackPayload.message?.ts || null
};
const rawBody = JSON.stringify(callbackBody);
const timestamp = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature: sig } }];
